package io.rowweave.expr;

import io.rowweave.DataSchema;
import io.rowweave.expr.codegen.AstBytecodeGenerator;
import io.rowweave.expr.codegen.UnsupportedExprException;

/**
 * Expression engine that compiles at run time: turns an {@link Expr} AST into a bytecode {@link CompiledExpr} with ASM, which removes the interpreter's per-row dispatch cost.
 *
 * <p>Correctness: the generated bytecode calls the same {@link ExprRuntime} static methods that {@link ExprInterpreter} calls, so the two produce byte-identical results.
 *
 * <p>Graceful degradation: a node the codegen does not cover, such as a named-parameter field fallback or a construct added later, throws
 * {@link UnsupportedExprException} and this engine catches it and falls back to {@link InterpretedExprEngine}, so a codegen gap never makes an
 * expression unavailable. {@link ExprEngineFactory#getDefault()} returns this engine and carries that fallback inside.
 */
public final class CompiledExprEngine implements ExprEngine {

    private final ExprEngine fallback = new InterpretedExprEngine();

    @Override
    public CompiledExpr compile(DataSchema meta, String expression) {
        return compile(meta, ExprParser.parse(expression));
    }

    @Override
    public CompiledExpr compile(DataSchema meta, Expr expression) {
        ExprSchema.validateReferences(meta, expression);
        try {
            return AstBytecodeGenerator.compile(meta, expression);
        } catch (UnsupportedExprException unsupported) {
            return fallback.compile(meta, expression); // graceful degradation to interpreter
        }
    }

    @Override
    public CompiledExpr compile(DataSchema meta, String expression, java.util.Map<String, Object> namedParams) {
        if (namedParams == null || namedParams.isEmpty()) {
            return compile(meta, expression);
        }
        ExprSchema.validateReferences(meta, ExprParser.parse(expression), namedParams);
        // named-param resolution (field-priority fallback) is interpreter-only for now.
        return fallback.compile(meta, expression, namedParams);
    }
}
